/**
 * @name Command injection via os.system or subprocess
 * @description Using os.system or subprocess with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Match os.system calls
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
    or
    // Match subprocess.call, subprocess.run, subprocess.Popen, etc.
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description File operations with untrusted input can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    )
    or
    // os.path operations that could be used for file access
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "chmod", "chown"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // shutil operations
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name SQL injection
 * @description Using database queries with untrusted input can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Match sqlite3, psycopg2, MySQLdb, etc. execute methods
    exists(API::CallNode call |
      (
        call = API::moduleImport("sqlite3").getMember(["execute", "executemany", "executescript"]).getACall() or
        call = API::moduleImport("psycopg2").getMember(["execute", "executemany"]).getACall() or
        call = API::moduleImport("MySQLdb").getMember(["execute", "executemany"]).getACall() or
        call = API::moduleImport("pymysql").getMember(["execute", "executemany"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"

/**
 * @name Format string injection
 * @description Using format strings with untrusted input can lead to information disclosure or code execution
 * @kind path-problem
 * @problem.severity warning
 * @id py/format-string-injection
 * @tags security
 *        external/cwe/cwe-134
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module FormatStringConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for str.format() calls
    exists(API::CallNode call |
      call = API::builtin("str").getMember("format").getACall() and
      sink = call.getArg(0)
    )
    or
    // Check for % formatting using API graph
    exists(API::CallNode call |
      call = API::builtin("str").getMember("__mod__").getACall() and
      sink = call.getArg(0)
    )
    or
    // Check for f-string formatting (though harder to exploit)
    exists(DataFlow::ExprNode expr |
      expr.asExpr() instanceof FormattedValue and
      sink = expr
    )
  }
}

module FormatStringFlow = TaintTracking::Global<FormatStringConfig>;
import FormatStringFlow::PathGraph

from FormatStringFlow::PathNode source, FormatStringFlow::PathNode sink
where FormatStringFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Format string injection from $@.", source.getNode(), "user input"
